			text = [=[The flask was empty but for a few drops of a glowing green liquid. Donova knew it at once for something like the sludge of {link:felwood}Felwood{/link}. The trail led to the camps of the {link:deadwood-furbolgs}Deadwood tribe{/link}, and from there to the toxic horrors of the {link:irontree-woods}Irontree Woods{/link}. When she mixed the poison with spring water, it lost its deadliness but kept its power over those who drank it. Now she understood why the {link:winterfall-furbolgs}Winterfall{/link} guarded the springs: they needed them to make their firewater.]=],
		},
		{
			key = "the-high-chief",
			title = "The High Chief",
			hint = "Put an end to the one who commands the Winterfall.",
			unlock = {
				{ type = "quest", id = 5121 },
			},
			text = [=[The {link:winterfall-furbolgs}Winterfall{/link} were never a violent tribe, Donova said. Only their chief could have set them on this path. She did not hope to undo what had been done, but she believed that without their leader they would sink no further. The chief carried a log written in marks so crude that she could not read them. She sent it south to {link:kelek-skykeeper}Kelek Skykeeper{/link}, a druid who knows the furbolgs of {link:felwood}Felwood{/link} well.]=],
		},
		{
			key = "the-source-of-the-springs",
			title = "The Source of the Springs",
			hint = [=[Travel south to where the air grows thick and the sky grows dark.]=],
			unlock = {
				{ type = "quest", id = 4842 },
			},
			text = [=[Donova did not believe the springs were warmed by the earth alone. She sent a traveller to the far south of {link:winterspring}Winterspring{/link}, where the air turns muggy and the sky darkens. There lay {link:darkwhisper-gorge}Darkwhisper Gorge{/link} and its demons. Donova now watches the springs for any further sign of their influence.]=],
		},
	},
	mentions = {
