Add({
	kind = "topic",
	id = "winterfall-furbolgs",
	title = "Winterfall Furbolgs",
	aliases = { "Winterfall", "Winterfall tribe" },
	category = "group",
	region = "winterspring",
	unlock = {
		{ type = "quest", id = 5082 },
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Winterfall are the {link:furbolgs}furbolg{/link} tribe of {link:winterspring}Winterspring{/link}. They were not a violent people, and they were long the allies of the {link:timbermaw-furbolgs}Timbermaw{/link}. That has changed. Their high chief has made strange demands of them, and now they fall upon anyone who strays close, beast or traveller, elf or goblin. They keep a village in the hills east of {link:everlook}Everlook{/link} and camps near the {link:frostfire-hot-springs}Frostfire Hot Springs{/link}.]=],
		},
		{
			title = "The Firewater",
			text = [=[The madness has a source. Runners of the tribe travel through {link:timbermaw-hold}Timbermaw Hold{/link} to the {link:deadwood-furbolgs}Deadwood{/link} furbolgs of {link:felwood}Felwood{/link}, who are themselves maddened by fel corruption. They bring back a green brew made from the poison of the toxic horrors of the {link:irontree-woods}Irontree Woods{/link}. Alone, it would kill them. Mixed with the water of the hot springs, it loses its deadliness but keeps its power, and those who drink it grow larger and more savage. This is why the Winterfall guard the springs so fiercely. The furbolgs still carry spirit beads to ward off evil spirits, but the beads have not saved them from what they have become.]=],
		},
	},
})

Add({
	kind = "topic",
	id = "crystal-of-zin-malor",
	title = "Crystal of Zin-Malor",
	category = "artifact",
	region = "winterspring",
	unlock = {
		{ type = "quest", id = 5245 },
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Crystal of Zin-Malor is a relic that can hold and command great arcane forces. Only the truly worthy can master it, and only a handful of the strongest mages could hope to. It bears the name of the {link:temple-of-zin-malor}Temple of Zin-Malor{/link}, which now lies in ruin in {link:azshara}Azshara{/link}. In ancient days the Highborne of {link:lake-kel-theril}Kel'Theril{/link} stole it, meaning to drain its power for themselves. In the attempt the crystal shattered in a great blast, and its pieces sank beneath the ice of the lake. The Highborne were cursed to remain there forever, still seeking the fragments.]=],
		},
		{
			title = "Remade",
			text = [=[In the present day, a {link:dwarves}dwarf{/link}'s pick broke the ice and brought up four fragments. The {link:high-elves}high elf{/link} {link:aurora-skycaller}Aurora Skycaller{/link} recognized them. With the sacred writings of the Highborne, recovered from the ruined temple in {link:azshara}Azshara{/link}, she made the crystal whole. It was shown to a spirit of {link:lake-kel-theril}Kel'Theril{/link} who repented of the old crime, and that spirit found peace. The crystal could never return to its temple. {link:wynd-nightchaser}Wynd Nightchaser{/link} of {link:starfall-village}Starfall{/link} sent it to {link:fandral-staghelm}Arch Druid Fandral Staghelm{/link} in {link:darnassus}Darnassus{/link}, who praised those who carried it for not trying to use it themselves.]=],
		},
	},
})
